// src/globals.ts
import global from "global";
var { window: globalWindow } = global;
globalWindow.STORYBOOK_ENV = "PIXI";

// src/helpers/PixiStory.ts
import { Container } from "pixi.js";
var PixiStory = class {
  constructor(options) {
    this.view = new Container();
    options.context.parameters.pixi.appReady.then(() => {
      options.init(this.view);
    });
    if (options.update !== void 0) {
      this.update = (ticker) => {
        options.update(this.view, ticker);
      };
    }
    if (options.resize !== void 0) {
      this.resize = (width, height) => {
        options.resize(this.view, width, height);
      };
    }
    if (options.destroy !== void 0) {
      this.destroy = () => {
        options.destroy(this.view);
      };
    }
  }
};

// src/index.ts
module?.hot?.decline();
export {
  PixiStory
};
